  const [favourites,setFavourites]=useStoredState('camy-favourites-v2',[]); const [settlements,setSettlements]=useState([]); const [cart,setCart]=useState([]); const [cartOpen,setCartOpen]=useState(false); const [notifyOpen,setNotifyOpen]=useState(false); const [globalQuery,setGlobalQuery]=useState(''); const [productModal,setProductModal]=useState(null); const [orderModal,setOrderModal]=useState(null); const [settlementModal,setSettlementModal]=useState(false); const [addEntrepreneur,setAddEntrepreneur]=useState(false); const [personModal,setPersonModal]=useState(null); const [addProduct,setAddProduct]=useState(false); const [addCategory,setAddCategory]=useState(false); const [toast,setToast]=useState('')
  const [stockRequests,setStockRequests]=useState([]); const [shopInventory,setShopInventory]=useState([])
